758	/** Parse a `psql --version` / `pg_config --version` banner into a major version.
759	 *  PostgreSQL ≥ 10 uses a single-number major ("15"); 9.x keeps major.minor. */
760	export function parsePgVersion(raw: string): string | null {
761	  const s = cleanText(raw, 200);
762	  const m = /(\d+(?:\.\d+)?)/.exec(s);
763	  if (!m) return null;
764	  const major = parseInt(m[1], 10);
765	  return Number.isFinite(major) && major >= 10 ? String(major) : m[1];
766	}
